let LANG=(()=>{try{const v=localStorage.getItem('t21lang');return STR[v]?v:'en';}catch(e){return 'en';}})();
/* t('cle', args…) : chaîne, fonction d'interpolation, ou tableau (mot au hasard) */
function t(key,...args){
  const dict=STR[LANG]||STR.en;
  const v=(key in dict)?dict[key]:STR.en[key];
  if(v===undefined)return key;
  return typeof v==='function'?v(...args):v;
}
function hasStr(key){return (STR[LANG]&&key in STR[LANG])||(key in STR.en);}

