function iName(o){return o?t(o.ns+'.'+o.id+'.n'):'';}
function iDesc(o){return o?t(o.ns+'.'+o.id+'.d'):'';}
const ED_NAME={foil:'FOIL',holo:'HOLO',poly:'POLY'};
